    (m mx : mem) (pad : list cell) (hjunk sh16 : list byte) (bflag : byte),
  rw_cells asegs mx spa pad -> Z.of_nat (cells_size pad) = bv_unsigned sp + -96 - spa -> lo <= spa ->
  rw_cells asegs mx (bv_unsigned sp + -96) (cr_frame w0 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra) ->
  rw_cells asegs mx ff [CB 120 hjunk; C8 (Z_to_bv 64 fp)] ->
  rw_cells asegs mx (Z.shiftr ff 3 + 2147450880) [CB 16 sh16] ->
  rw_cells asegs mx fp [C1 bflag] ->
  stk asegs mx lo spa -> mem_inv asegs mx ->
  as_RFS H ((1, ff, fp) :: LF) mx -> fresh_frame H LF 1 ff fp -> ACONST mx -> stack0 mx lo shi ->
  munch (cr_W H lo sp stb ff fp) m mx -> wmono asegs m mx ->
  (forall m', munch [(ff, ff + 8); (Z.shiftr ff 3 + 2147450880, Z.shiftr ff 3 + 2147450880 + 16); (fp, fp + 1)]%Z mx m' -> wmono asegs mx m' ->
     AStateBlock LB m' stb ioc implb (st_closed S) ds /\ ACanaryReads m') ->
  lo + 112 <= bv_unsigned sp -> aceil <= lo -> bv_unsigned ra mod 2 = 0 ->
  evt asegs (close_remote_post H ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc LB LF stb ioc implb lo shi S ds m)
    (MS (mkR rax (Z_to_bv 64 spa) gp tp t0' t1' t2' sp xs1 a0' a1' a2' a3' a4' a5' a6' a7'
             (Z_to_bv 64 ff) xs3 xs4 xs5 (Z_to_bv 64 (Z.shiftr ff 3 + 2147450880)) (Z_to_bv 64 ff) (Z_to_bv 64 2147450880) xs9 s10 s11 t3' t4' t5' t6')
        F (Z_to_bv 64 ACR_EXIT) fc None mx (seg_rom asegs)).
