(* [comment removed for export] *)
Lemma addressable_crm : forall LF ff fp m0 m1 m2 stb lo sp,
  as_RFS H LF m0 -> fresh_frame H LF 1 ff fp -> aceil <= lo ->
  addressable m1 stb SZ_SPCI_STATE -> aapp stb SZ_SPCI_STATE -> fsobj H LF stb SZ_SPCI_STATE ->
