(* [comment removed for export] *)
Ltac fs_bundle_now HH RFc ACc SK2 FF MU3 WM3 W3K RFx ACx SKx :=
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mc _) =>
    lazymatch type of SK2 with stack0 _ ?lo ?shi => lazymatch type of RFc with as_RFS ?H ?LFc _ =>
    let B := fresh "BND" in
    assert (B : as_RFS H LFc mc /\ ACONST mc /\ stack0 mc lo shi)
      by (eapply (fs_frame_writes_obj _ HH); [exact RFc| exact ACc| exact SK2| exact FF| exact MU3| exact WM3| exact W3K]);
    destruct B as (RFx & ACx & SKx) end end end.

(* [comment removed for export] *)
Ltac acc_now AC MU3 WFR F1 F3 SEP ACn :=
  lazymatch type of AC with accessible _ ?O ?n =>
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mc _) =>
    assert (ACn : accessible mc O n)
      by (eapply (accessible_transport_fr _ _ mc O n _ 16); [exact AC| exact MU3| exact WFR| clear - F1; lia| exact F3| clear; lia| clear - SEP; unhideL; lia])
  end end.

(* [comment removed for export] *)
Lemma cr_mid : forall (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (rax t0' t1' t2' a0' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' w0 : word)
    (bs stb ioc implb spa lo shi ff fp : Z) (LB : list block) (LF : list fframe) (S : statev) (ds : list byte)
    (m m2 : mem) (pad : list cell) (hjunk : list byte),
  rw_cells asegs m2 spa pad -> Z.of_nat (cells_size pad) = bv_unsigned sp + -96 - spa -> lo + 112 <= spa -> spa + 96 <= bv_unsigned sp ->
  rw_cells asegs m2 (bv_unsigned sp + -96) (cr_frame w0 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra) ->
  rw_cells asegs m2 ff [CB 120 hjunk; C8 (Z_to_bv 64 fp)] ->
  rw_cells asegs m2 (Z.shiftr ff 3 + 2147450880)
     [C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0);
      C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0)] ->
  rw_cells asegs m2 fp [C1 (b8 1)] ->
  stk asegs m2 lo spa -> mem_inv asegs m2 ->
  as_RFS H ((1, ff, fp) :: LF) m2 -> fresh_frame H LF 1 ff fp -> ACONST m2 -> stack0 m2 lo shi ->
  as_RFS H LF m ->
  munch (cr_W H lo sp stb ff fp) m m2 -> wmono asegs m m2 ->
  ro_cells asegs m2 bs [C8 (wz (stb + 32))] -> bs mod 8 = 0 ->
  AStateBlock LB m2 stb ioc implb S ds -> st_lk S = 0 ->
  (st_fb S <> FB_empty -> fb_end (st_fb S) <= stb \/ stb + SZ_SPCI_STATE <= fb_begin (st_fb S)) ->
  ACanaryReads m2 ->
  (bs + 8 <= stb \/ stb + SZ_SPCI_STATE <= bs) ->
  aplace bs 8 -> (bs + 8 <= lo \/ bv_unsigned sp <= bs) -> fsobj H LF bs 8 -> accessible m2 bs 8 ->
  fsobj H LF stb SZ_SPCI_STATE ->
  (st_fb S <> FB_empty -> fsobj H LF (fb_begin (st_fb S)) (fb_cap (st_fb S))) ->
  aceil <= lo -> bv_unsigned ra mod 2 = 0 ->
  evt asegs (close_remote_post H ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc LB LF stb ioc implb lo shi S ds m)
    (MS (mkR rax (Z_to_bv 64 spa) gp tp t0' t1' t2' sp (Z_to_bv 64 spa) a0' a1' a2' a3' a4' a5' a6' a7'
             (Z_to_bv 64 ff) s3 (Z_to_bv 64 bs) s5 s6 (Z_to_bv 64 ff) (Z_to_bv 64 2147450880) s9 s10 s11 t3' t4' t5' t6')
